<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import {request} from '@/services/quality'
import {officineService,accountState} from '@/services/officine'
const route=useRoute();const platform=computed(()=>route.path.startsWith('/beg'))
interface Dossier {id:number;name:string;status:string;email:string;phone:string|null;city:string|null;address:string|null;applicant_function:string|null;country:string|null;department:string|null;contact_name:string|null;district:string|null;neighborhood:string|null;latitude:number|null;longitude:number|null;application_version:number;review_note:string|null;reviewer_id?:number}
const items=ref<Dossier[]>([]);const selected=ref<Dossier|null>(null);const query=ref('');const filter=ref('');const loading=ref(false);const busy=ref(false);const error=ref('');const notice=ref('');const detail=ref(false);const editor=ref(false);const confirm=ref(false);const action=ref('');const note=ref('');const internal=ref(false);const consent=ref(false)
const comments=ref<{id:number;message:string;is_internal:boolean;created_at:string}[]>([]);const documents=ref<{id:number;name:string;type:string;size:number}[]>([]);const file=ref<File|null>(null);const fileType=ref('Justificatif facultatif');const form=ref<Record<string,string|number|null>>({})
const labels:Record<string,string>={draft:'Brouillon',pending:'Soumise',under_review:'En instruction',corrections_requested:'Corrections demandées',active:'Approuvée',rejected:'Refusée'}
const filtered=computed(()=>items.value.filter(a=>(!filter.value||a.status===filter.value)&&(a.name+' '+a.city+' '+a.email).toLowerCase().includes(query.value.toLowerCase())))
async function load(){loading.value=true;error.value='';try{await officineService.account();items.value=(await request<{data:Dossier[]}>(platform.value?'/platform/applications':'/applications')).data}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function inspect(a:Dossier){selected.value=a;detail.value=true;error.value='';try{[comments.value,documents.value]=await Promise.all([request<{data:typeof comments.value}>(`/registration-applications/${a.id}/comments`).then(x=>x.data),request<{data:typeof documents.value}>(`/registration-applications/${a.id}/documents`).then(x=>x.data)])}catch(e){error.value=(e as Error).message}}
function edit(){const a=selected.value!;form.value={officine_name:a.name,phone:a.phone||'',city:a.city||'',address:a.address||'',applicant_function:a.applicant_function||'',country:a.country||'Bénin',department:a.department||'',contact_name:a.contact_name||'',district:a.district||'',neighborhood:a.neighborhood||'',latitude:a.latitude,longitude:a.longitude};editor.value=true;error.value=''}
function decide(type:string){action.value=type;note.value='';internal.value=false;consent.value=false;error.value='';confirm.value=true}
async function save(){busy.value=true;error.value='';try{const fields=Object.fromEntries(Object.entries(form.value).filter(([,v])=>v!==''&&v!==null));await request('/registration-applications/'+selected.value!.id,'PATCH',{...fields,version:selected.value!.application_version});editor.value=false;detail.value=false;notice.value='Brouillon enregistré, non soumis.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function execute(){busy.value=true;error.value='';try{if(action.value==='create'){await request('/registration-applications','POST')}
else if(action.value==='verify'){await request('/auth/email/request','POST');notice.value='Lien de vérification préparé. Consultez Notifications.'}
else if(action.value==='submit'){await request(`/registration-applications/${selected.value!.id}/submit`,'POST',{version:selected.value!.application_version,consent:consent.value})}
else if(action.value==='comment'){await request(`/registration-applications/${selected.value!.id}/comments`,'POST',{message:note.value,is_internal:internal.value});await inspect(selected.value!)}
else {await request(`/platform/applications/${selected.value!.id}/decision`,'POST',{version:selected.value!.application_version,decision:action.value,habilitation_confirmed:action.value==='active'?consent.value:undefined,note:note.value||undefined})}
confirm.value=false;if(action.value!=='comment')detail.value=false;await load()
}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function upload(){if(!file.value)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file.value);body.append('type',fileType.value);const res=await fetch(`/api/v1/registration-applications/${selected.value!.id}/documents`,{method:'POST',headers:{Accept:'application/json',Authorization:'Bearer '+sessionStorage.getItem('bestpharma.token')},body});const d=await res.json();if(!res.ok)throw new Error(Object.values(d.errors||{}).flat().join(' ')||d.message);file.value=null;await inspect(selected.value!)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function download(id:number){error.value='';try{const res=await fetch(`/api/v1/registration-applications/${selected.value!.id}/documents/${id}`,{headers:{Accept:'application/octet-stream',Authorization:'Bearer '+sessionStorage.getItem('bestpharma.token')}});if(!res.ok)throw new Error('Téléchargement non autorisé ou indisponible.');const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;a.download='piece-'+id;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
onMounted(load)
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">{{platform?'INSTRUCTION ADMINISTRATIVE':'OUVERTURE D’OFFICINE'}}</p><h1>{{platform?'Demandes d’inscription':'Mes dossiers d’ouverture'}}</h1><p class="page-subtitle">Brouillon → soumission vérifiée → instruction → décision. Aucune autorisation pharmaceutique implicite.</p></div><button v-if="!platform" class="button primary" @click="decide('create')">Nouvelle demande</button><button class="button secondary" :disabled="loading||busy" @click="load">Actualiser</button></div><p v-if="error&&!detail&&!confirm" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><div v-if="!platform&&!accountState.user?.email_verified" class="module-callout"><div><strong>Vérification de l’adresse email nécessaire avant soumission</strong><p>Vous pouvez préparer votre brouillon. L’instruction n’est ouverte qu’après vérification et soumission.</p><div class="module-links"><button class="button primary" @click="decide('verify')">Demander la vérification</button><RouterLink to="/notifications" class="button secondary">Notifications & livraison</RouterLink></div></div></div><div class="panel overview-recent"><div class="table-toolbar"><label class="search-field"><input v-model="query" aria-label="Rechercher un dossier" placeholder="Officine, commune, email…"/></label><select v-model="filter" aria-label="État du dossier" style="max-width:220px"><option value="">Tous les états</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></div><p v-if="loading" role="status">Chargement…</p><div v-else class="table-scroll"><table><thead><tr><th>OFFICINE</th><th>COMMUNE</th><th>ÉTAT</th><th>VERSION</th><th>ACTION</th></tr></thead><tbody><tr v-for="a in filtered" :key="a.id"><td>{{a.name}}<span class="table-subtitle">#{{a.id}} · {{a.email}}</span></td><td>{{a.city||'À compléter'}}</td><td><span class="status-badge" :class="a.status">{{labels[a.status]||a.status}}</span></td><td>{{a.application_version}}</td><td><button class="button secondary small" @click="inspect(a)">Ouvrir</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty-state">Aucun dossier à afficher.</td></tr></tbody></table></div></div>
<AppModal v-model="detail" :title="selected?.name||'Dossier'" size="wide" :busy="busy"><div v-if="selected" class="form-body"><p v-if="error&&!editor&&!confirm" class="alert error" role="alert">{{error}}</p><dl class="application-summary"><dt>État / version</dt><dd>{{labels[selected.status]}} · v{{selected.application_version}}</dd><dt>Localisation</dt><dd>{{selected.country}} · {{selected.department}} · {{selected.city}} · {{selected.address}}</dd><dt>Responsable</dt><dd>{{selected.contact_name}} · {{selected.applicant_function}} · {{selected.phone}}</dd><dt>Dernier message</dt><dd>{{selected.review_note||'Aucun'}}</dd></dl><h3>Pièces facultatives</h3><p class="module-disclaimer">Aucune pièce réglementaire n’est imposée. PDF, PNG, JPEG, 5 Mo maximum. Stockage privé ; analyse antivirus non disponible.</p><div v-for="d in documents" :key="d.id" class="detail-card section-toolbar"><div><strong>{{d.name}}</strong><p class="page-subtitle">{{d.type}} · {{Math.ceil(d.size/1024)}} Ko</p></div><button class="button secondary small" @click="download(d.id)">Télécharger</button></div><form v-if="!platform&&['draft','corrections_requested'].includes(selected.status)" class="correction-form" @submit.prevent="upload"><label>Type de pièce<input v-model="fileType" maxlength="120" required/></label><label>Fichier privé<input type="file" accept="application/pdf,image/png,image/jpeg" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></label><button :disabled="busy||!file" class="button secondary">Ajouter la pièce</button></form><h3>Messages et décisions</h3><article v-for="c in comments" :key="c.id" class="comment-card"><strong>{{c.is_internal?'Note interne — entreprise':'Message partagé'}}</strong><small>{{c.created_at}} UTC</small><p>{{c.message}}</p></article><button class="button secondary" @click="decide('comment')">Ajouter un message</button></div><template #footer><button class="button secondary" :disabled="busy" @click="detail=false">Fermer</button><template v-if="selected"><template v-if="!platform&&['draft','corrections_requested'].includes(selected.status)"><button class="button secondary" @click="edit">Modifier le brouillon</button><button class="button primary" @click="decide('submit')">Soumettre le dossier</button></template><RouterLink v-if="!platform&&selected.status==='active'" to="/choose-officine" class="button primary" @click="detail=false">Ouvrir mon espace</RouterLink><button v-if="platform&&selected.status==='pending'" class="button primary" @click="decide('under_review')">Prendre en charge</button><template v-if="platform&&selected.status==='under_review'"><button class="button secondary" @click="decide('corrections_requested')">Demander des corrections</button><button class="button danger" @click="decide('rejected')">Refuser</button><button class="button primary" @click="decide('active')">Approuver</button></template></template></template></AppModal>
<AppModal v-model="editor" title="Modifier mon brouillon" size="wide" :busy="busy"><form id="draft-form" class="form-body form-grid" @submit.prevent="save"><p v-if="error" role="alert" class="alert error span-2">{{error}}</p><label v-for="f in [{k:'officine_name',l:'Nom de l’officine'},{k:'phone',l:'Téléphone'},{k:'country',l:'Pays'},{k:'department',l:'Département'},{k:'city',l:'Commune'},{k:'contact_name',l:'Nom du responsable'},{k:'applicant_function',l:'Fonction du demandeur'},{k:'address',l:'Adresse descriptive'},{k:'district',l:'Arrondissement (facultatif)'},{k:'neighborhood',l:'Quartier (facultatif)'}]" :key="f.k">{{f.l}}<input v-model="form[f.k]" :maxlength="f.k==='address'?500:120"/></label><label>Latitude (facultatif)<input v-model="form.latitude" type="number" step="any" min="-90" max="90"/></label><label>Longitude (facultatif)<input v-model="form.longitude" type="number" step="any" min="-180" max="180"/></label><p class="module-disclaimer span-2">L’enregistrement n’envoie pas le dossier à l’instruction. Les champs obligatoires seront contrôlés lors de la soumission.</p></form><template #footer><button :disabled="busy" class="button secondary" @click="editor=false">Annuler</button><button :disabled="busy" class="button primary" form="draft-form" type="submit">Enregistrer le brouillon</button></template></AppModal>
<AppModal v-model="confirm" :title="action==='create'?'Créer un brouillon ?':action==='verify'?'Demander la vérification email ?':action==='comment'?'Ajouter un message':'Confirmer la décision'" :busy="busy"><form id="application-confirm" class="form-body correction-form" @submit.prevent="execute"><p v-if="error" class="alert error" role="alert">{{error}}</p><template v-if="action==='submit'"><p>Le dossier doit être complet et votre email vérifié. Cette demande ne constitue pas une autorisation pharmaceutique.</p><label class="checkbox-label"><input v-model="consent" type="checkbox" required/>Je confirme l’exactitude des informations et mon habilitation à soumettre ce dossier.</label></template><label v-if="action==='active'" class="checkbox-label"><input v-model="consent" type="checkbox" required/>Je confirme avoir contrôlé l’habilitation du demandeur à agir pour cette officine. Les justificatifs restent facultatifs ; cette validation ne vaut pas autorisation réglementaire.</label><label v-if="['comment','active','under_review','rejected','corrections_requested'].includes(action)">Message {{['comment','rejected','corrections_requested'].includes(action)?'(obligatoire)':'(facultatif)'}}<textarea v-model="note" :required="['comment','rejected','corrections_requested'].includes(action)" maxlength="2000" rows="4"/></label><label v-if="action==='comment'&&platform" class="checkbox-label"><input v-model="internal" type="checkbox"/>Note interne, invisible du demandeur</label><p v-if="action==='create'">Un brouillon incomplet privé sera créé ou repris pour votre compte.</p><p v-if="action==='verify'">Le lien sera préparé dans l’outbox. Consultez son état de livraison dans Notifications.</p></form><template #footer><button :disabled="busy" class="button secondary" @click="confirm=false">Annuler</button><button :disabled="busy" class="button primary" form="application-confirm" type="submit">Confirmer</button></template></AppModal></section></template>
